css:
:root {
  --paper: #F3EFE3;
  --paper-bright: #FAF7EE;
  --ink: #122019;
  --ink-soft: #33423A;
  --muted: #57625B;
  --forest: #174333;
  --forest-deep: #0B2017;
  --forest-bright: #2B6249;
  --lime: #DCEB6A;
  --lime-soft: #EDF3CC;
  --clay: #B4532E;
  --clay-ink: #8B3A20;
  --clay-soft: #F5E4DA;
  --line: rgba(18, 32, 25, 0.13);
  --line-strong: rgba(18, 32, 25, 0.24);
  --cream: #F6F2E7;
  --sans: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  --serif: ui-serif, Georgia, "Times New Roman", Times, serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
  --wrap: 1180px;
  --radius: 10px;
}

*,
*::before,
*::after { box-sizing: border-box; }

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.5;
  overflow-x: clip;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1, h2, h3, p, figure { margin: 0; }
ul, ol { margin: 0; padding: 0; list-style: none; }
svg { display: block; }
a { color: inherit; }

::selection { background: var(--lime); color: var(--ink); }

.wrap {
  width: min(var(--wrap), calc(100% - 40px));
  margin-inline: auto;
}

.skip-link {
  position: absolute;
  top: -64px;
  left: 16px;
  z-index: 100;
  padding: 12px 16px;
  background: var(--ink);
  color: var(--cream);
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  border-radius: 8px;
  transition: top 160ms ease;
}
.skip-link:focus { top: 16px; }

#features,
#how,
#start { scroll-margin-top: 88px; }

a:focus-visible,
button:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 3px;
}

/* ---------- Nav ---------- */

.site-head {
  position: sticky;
  top: 0;
  z-index: 20;
  background: rgba(243, 239, 227, 0.88);
  -webkit-backdrop-filter: blur(14px);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--line);
}

.nav {
  min-height: 74px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.025em;
  text-decoration: none;
  white-space: nowrap;
}

.brand-mark { flex: none; }

.nav-links {
  display: flex;
  align-items: center;
  gap: 30px;
  margin-left: auto;
  margin-right: 8px;
}

.nav-links a {
  font-size: 14px;
  font-weight: 500;
  color: var(--ink-soft);
  text-decoration: none;
  text-underline-offset: 5px;
  text-decoration-thickness: 1px;
  transition: color 160ms ease;
}

.nav-links a:hover {
  color: var(--forest);
  text-decoration: underline;
}

/* ---------- Buttons ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 52px;
  padding: 0 22px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  font-family: var(--sans);
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 180ms ease, border-color 180ms ease, color 180ms ease, transform 180ms ease;
}

.btn svg { flex: none; transition: transform 180ms ease; }

.btn--primary {
  background: var(--forest);
  color: var(--cream);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12), 0 8px 20px -10px rgba(11, 32, 23, 0.55);
}
.btn--primary:hover {
  background: #0E3527;
  transform: translateY(-1px);
}
.btn--primary:hover svg { transform: translateX(3px); }
.btn--primary:active { transform: translateY(0); }

.btn--ghost {
  background: transparent;
  border-color: var(--line-strong);
  color: var(--ink);
}
.btn--ghost:hover {
  background: rgba(18, 32, 25, 0.055);
  border-color: var(--ink);
}

.btn--sm {
  min-height: 40px;
  padding: 0 16px;
  font-size: 13.5px;
  border-radius: 8px;
}

.btn--ink {
  background: var(--ink);
  color: var(--cream);
  box-shadow: 0 10px 24px -12px rgba(18, 32, 25, 0.6);
}
.btn--ink:hover {
  background: #07120C;
  transform: translateY(-1px);
}
.btn--ink:hover svg { transform: translateX(3px); }

.btn--outline-ink {
  background: transparent;
  border-color: rgba(18, 32, 25, 0.38);
  color: var(--ink);
}
.btn--outline-ink:hover {
  background: rgba(18, 32, 25, 0.08);
  border-color: var(--ink);
}

/* ---------- Shared type ---------- */

.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 18px;
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 500;
  line-height: 1;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

.eyebrow::before {
  content: "";
  width: 22px;
  height: 1px;
  flex: none;
  background: currentColor;
  opacity: 0.55;
}

.section-title {
  font-size: clamp(2rem, 3.7vw, 3.3rem);
  font-weight: 600;
  line-height: 1.02;
  letter-spacing: -0.042em;
  max-width: 17ch;
  text-wrap: balance;
}

.section-lede {
  max-width: 36ch;
  padding-bottom: 6px;
  color: var(--muted);
  font-size: 15.5px;
  line-height: 1.6;
}

.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 40px;
  margin-bottom: clamp(44px, 5vw, 64px);
}

/* ---------- Hero ---------- */

.hero {
  position: relative;
  overflow: clip;
  background:
    radial-gradient(1000px 560px at 92% -14%, rgba(220, 235, 106, 0.34), transparent 62%),
    radial-gradient(760px 520px at -12% 38%, rgba(23, 67, 51, 0.06), transparent 65%),
    var(--paper);
}

.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent 35px,
    rgba(18, 32, 25, 0.038) 35px,
    rgba(18, 32, 25, 0.038) 36px
  );
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 16%, #000 82%, transparent);
  mask-image: linear-gradient(to bottom, transparent, #000 16%, #000 82%, transparent);
}

.hero-grid {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
  align-items: center;
  gap: clamp(40px, 5vw, 76px);
  padding-top: clamp(52px, 7vw, 100px);
  padding-bottom: clamp(64px, 8vw, 112px);
}

.hero-copy { position: relative; z-index: 2; }

.hero-pill {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  gap: 9px;
  margin-bottom: clamp(24px, 3vw, 34px);
  padding: 8px 13px 8px 11px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  background: rgba(250, 247, 238, 0.62);
  font-family: var(--mono);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.1em;
  line-height: 1.25;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.hero-pill .pip {
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 50%;
  background: var(--forest);
  box-shadow: 0 0 0 3px rgba(220, 235, 106, 0.9);
}

.hero-title {
  max-width: 10em;
  font-size: clamp(2.6rem, 6.5vw, 4.5rem);
  font-weight: 600;
  line-height: 0.99;
  letter-spacing: -0.045em;
}

.hero-title em {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: 1.045em;
  letter-spacing: -0.03em;
}

.hero-sub {
  max-width: 46ch;
  margin-top: clamp(20px, 2.4vw, 28px);
  color: var(--muted);
  font-size: clamp(1rem, 1.25vw, 1.125rem);
  line-height: 1.6;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: clamp(28px, 3.4vw, 40px);
}

.hero-note {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 26px;
  font-family: var(--mono);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.11em;
  line-height: 1.4;
  text-transform: uppercase;
  color: var(--muted);
}

.hero-note::before {
  content: "";
  width: 26px;
  height: 1px;
  flex: none;
  background: var(--line-strong);
}

/* ---------- Hero artwork ---------- */

.hero-art {
  position: relative;
  z-index: 1;
  height: clamp(420px, 40vw, 548px);
  display: grid;
  place-items: center;
}

.art-panel {
  position: absolute;
  inset: 6% 1% 5% 1%;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 28px;
  background-color: #0F2C20;
  background-image:
    radial-gradient(120% 100% at 82% -8%, rgba(92, 158, 122, 0.75), transparent 55%),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.045) 0, rgba(255, 255, 255, 0.045) 1px, transparent 1px, transparent 56px),
    repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.045) 0, rgba(255, 255, 255, 0.045) 1px, transparent 1px, transparent 56px);
  box-shadow: 0 48px 90px -48px rgba(8, 26, 18, 0.85);
}

.art-panel::after {
  content: "";
  position: absolute;
  top: -86px;
  right: -92px;
  width: 240px;
  height: 240px;
  border: 1px solid rgba(220, 235, 106, 0.38);
  border-radius: 50%;
}

.art-orb {
  position: absolute;
  z-index: 1;
  top: 1%;
  right: 2%;
  width: 25%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #EAF59C, var(--lime) 62%, #C6D94A 100%);
  box-shadow: 0 22px 44px -18px rgba(8, 26, 18, 0.6);
}

.ledger {
  position: relative;
  z-index: 2;
  width: min(86%, 424px);
  padding: 18px;
  border: 1px solid rgba(18, 32, 25, 0.14);
  border-radius: 16px;
  background: var(--paper-bright);
  box-shadow:
    0 34px 64px -22px rgba(4, 16, 10, 0.65),
    0 2px 5px rgba(4, 16, 10, 0.2);
  transform: rotate(-2.2deg);
}

.ledger-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.ledger-kicker {
  display: block;
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.14em;
  line-height: 1;
  text-transform: uppercase;
  color: var(--muted);
}

.ledger-title {
  display: block;
  margin-top: 6px;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.025em;
  line-height: 1.1;
}

.status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 9px;
  border: 1px solid rgba(23, 67, 51, 0.16);
  border-radius: 999px;
  background: var(--lime-soft);
  font-family: var(--mono);
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: 0.09em;
  line-height: 1;
  text-transform: uppercase;
  color: var(--forest);
  white-space: nowrap;
}

.status-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--forest);
}

.ledger-rows {
  margin-top: 15px;
  border-top: 1px solid rgba(18, 32, 25, 0.12);
}

.ledger-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px dashed rgba(18, 32, 25, 0.13);
}

.cat {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  flex: none;
  border-radius: 8px;
  color: var(--forest);
}

.cat--a { background: var(--lime-soft); }
.cat--b { background: #E9E6D6; }
.cat--c { background: var(--clay-soft); color: var(--clay-ink); }

.row-name {
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: -0.012em;
  color: var(--ink);
}

.row-bar {
  width: 72px;
  height: 6px;
  margin-left: auto;
  flex: none;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(18, 32, 25, 0.09);
}

.row-bar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--forest-bright);
}

.w-1 { width: 78%; }
.w-2 { width: 56%; }
.w-3 { width: 38%; }

.row-check {
  flex: none;
  margin-left: 2px;
  color: var(--forest-bright);
}

.ledger-row--flag {
  margin: 10px -5px 2px;
  padding: 9px 10px;
  border: 1px solid rgba(180, 83, 46, 0.3);
  border-radius: 10px;
  background: var(--clay-soft);
}

.ledger-row--flag .cat {
  width: 24px;
  height: 24px;
  border-radius: 6px;
  background: var(--clay);
  color: #FFF9F4;
}

.flag-pill {
  margin-left: auto;
  padding: 4px 7px;
  border: 1px solid rgba(139, 58, 32, 0.28);
  border-radius: 999px;
  background: #FFF8F2;
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.08em;
  line-height: 1.1;
  text-transform: uppercase;
  color: var(--clay-ink);
  white-space: nowrap;
}

.ledger-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-top: 13px;
}

.foot-label {
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.12em;
  line-height: 1;
  text-transform: uppercase;
  color: var(--muted);
}

.foot-arrow {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  flex: none;
  border: 1px solid var(--line-strong);
  border-radius: 50%;
  color: var(--forest);
}

.chip {
  position: absolute;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 13px;
  border: 1px solid rgba(18, 32, 25, 0.13);
  border-radius: 999px;
  background: var(--paper-bright);
  box-shadow: 0 18px 38px -14px rgba(4, 16, 10, 0.5);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: -0.005em;
  line-height: 1;
  white-space: nowrap;
}

.chip-dot {
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 50%;
}

.chip-dot--lime {
  background: #9DB331;
  box-shadow: 0 0 0 3px rgba(220, 235, 106, 0.55);
}

.chip-dot--clay {
  background: var(--clay);
  box-shadow: 0 0 0 3px rgba(180, 83, 46, 0.16);
}

.chip--auto {
  top: 6%;
  right: 3%;
}

.chip--dupe {
  bottom: 5%;
  left: 2%;
}

@keyframes drift {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-7px); }
}

@keyframes soft-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

@media (prefers-reduced-motion: no-preference) {
  .chip--auto { animation: drift 7s ease-in-out infinite; }
  .chip--dupe { animation: drift 8.5s ease-in-out 1.2s infinite reverse; }
  .status-dot { animation: soft-pulse 2.8s ease-in-out infinite; }
}

/* ---------- Features ---------- */

.features {
  padding-block: clamp(64px, 8vw, 112px);
  border-top: 1px solid var(--line);
  background: var(--paper-bright);
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 1px solid var(--line-strong);
}

.feature {
  padding: 30px clamp(18px, 2.4vw, 34px) 4px 0;
}

.feature + .feature {
  padding-left: clamp(18px, 2.4vw, 34px);
  border-left: 1px solid var(--line);
}

.feature-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 26px;
}

.feature-icon {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border: 1px solid rgba(23, 67, 51, 0.16);
  border-radius: 12px;
  background: var(--lime-soft);
  color: var(--forest);
}

.feature-num {
  font-family: var(--mono);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.11em;
  line-height: 1;
  color: var(--muted);
}

.feature h3 {
  margin-bottom: 12px;
  font-size: clamp(1.2rem, 1.8vw, 1.45rem);
  font-weight: 600;
  letter-spacing: -0.028em;
  line-height: 1.15;
}

.feature p {
  max-width: 37ch;
  color: var(--muted);
  font-size: 15.5px;
  line-height: 1.66;
}

/* ---------- How it works ---------- */

.how {
  position: relative;
  overflow: clip;
  padding-block: clamp(64px, 8vw, 112px);
  background:
    radial-gradient(900px 520px at 88% -6%, rgba(48, 106, 79, 0.6), transparent 62%),
    var(--forest-deep);
  color: var(--cream);
}

.how::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: repeating-linear-gradient(
    to right,
    transparent 0,
    transparent calc(25% - 1px),
    rgba(244, 240, 228, 0.05) calc(25% - 1px),
    rgba(244, 240, 228, 0.05) 25%
  );
}

.how .wrap { position: relative; z-index: 1; }

.how .eyebrow { color: var(--lime); }

.how .section-title {
  max-width: 16ch;
  color: var(--cream);
}

.how .section-lede { color: rgba(244, 240, 228, 0.68); }

.steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(28px, 4vw, 56px);
  position: relative;
}

.steps::before {
  content: "";
  position: absolute;
  top: 23px;
  left: 23px;
  right: 23px;
  border-top: 1px dashed rgba(220, 235, 106, 0.36);
}

.step { position: relative; }

.step-num {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  margin-bottom: 22px;
  border: 1px solid rgba(220, 235, 106, 0.52);
  border-radius: 50%;
  background: var(--forest-deep);
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.08em;
  color: var(--lime);
}

.step h3 {
  margin-bottom: 9px;
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -0.022em;
  line-height: 1.2;
  color: var(--cream);
}

.step p {
  max-width: 32ch;
  color: rgba(244, 240, 228, 0.68);
  font-size: 14.5px;
  line-height: 1.62;
}

/* ---------- Closing CTA ---------- */

.cta {
  position: relative;
  overflow: clip;
  padding-block: clamp(68px, 9vw, 118px);
  background:
    radial-gradient(800px 420px at 88% -18%, rgba(255, 255, 255, 0.5), transparent 64%),
    var(--lime);
  color: var(--ink);
}

.cta::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent 47px,
    rgba(18, 32, 25, 0.07) 47px,
    rgba(18, 32, 25, 0.07) 48px
  );
  -webkit-mask-image: linear-gradient(to right, #000, transparent 55%);
  mask-image: linear-gradient(to right, #000, transparent 55%);
}

.cta-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(28px, 5vw, 64px);
}

.cta-copy { max-width: 760px; }

.cta .eyebrow {
  margin-bottom: 20px;
  color: #46512B;
}

.cta-title {
  max-width: 15ch;
  font-size: clamp(2.4rem, 5.2vw, 4.5rem);
  font-weight: 600;
  line-height: 0.99;
  letter-spacing: -0.045em;
  text-wrap: balance;
}

.cta-title em {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: 1.045em;
  letter-spacing: -0.03em;
}

.cta-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: clamp(28px, 3.4vw, 40px);
}

.cta-mark {
  display: grid;
  place-items: center;
  width: clamp(132px, 15vw, 184px);
  aspect-ratio: 1;
  border: 1px solid rgba(18, 32, 25, 0.3);
  border-radius: 50%;
  color: var(--ink);
}

.cta-mark svg { width: 38%; height: auto; }

/* ---------- Footer ---------- */

.footer {
  padding-block: 34px;
  border-top: 1px solid var(--line);
  background: var(--paper);
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 18px 32px;
}

.footer-tag {
  margin-left: auto;
  margin-right: auto;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

.footer-legal {
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.1em;
  line-height: 1.5;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- Responsive ---------- */

@media (max-width: 980px) {
  .hero-grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 44px;
    padding-top: clamp(44px, 7vw, 72px);
  }

  .hero-copy { max-width: 680px; }

  .hero-art {
    width: min(100%, 560px);
    height: clamp(400px, 62vw, 500px);
    margin-inline: auto;
  }

  .ledger { width: min(80%, 420px); }

  .chip--auto { top: 4%; right: 4%; }
  .chip--dupe { bottom: 4%; left: 3%; }

  .section-head { align-items: flex-start; flex-direction: column; gap: 20px; }

  .feature { padding-right: clamp(14px, 2vw, 24px); }
  .feature + .feature { padding-left: clamp(14px, 2vw, 24px); }

  .steps { gap: 26px; }
}

@media (max-width: 820px) {
  .nav-links { display: none; }

  .feature-grid { grid-template-columns: minmax(0, 1fr); }

  .feature {
    padding: 26px 0 26px;
  }

  .feature + .feature {
    padding-left: 0;
    border-left: 0;
    border-top: 1px solid var(--line);
  }

  .feature-top { margin-bottom: 20px; }

  .feature:first-child { padding-top: 30px; }

  .feature p { max-width: 52ch; }

  .steps {
    grid-template-columns: minmax(0, 1fr);
    gap: 30px;
  }

  .steps::before {
    top: 23px;
    bottom: 23px;
    left: 23px;
    right: auto;
    border-top: 0;
    border-left: 1px dashed rgba(220, 235, 106, 0.36);
  }

  .step {
    display: grid;
    grid-template-columns: 46px minmax(0, 1fr);
    column-gap: 18px;
  }

  .step-num {
    grid-row: 1 / span 2;
    margin-bottom: 0;
  }

  .step h3 { margin-top: 2px; }

  .step p { max-width: 46ch; }

  .cta-inner { grid-template-columns: minmax(0, 1fr); }

  .cta-mark { display: none; }
}

@media (max-width: 560px) {
  .wrap { width: calc(100% - 36px); }

  .nav { min-height: 66px; }

  .brand { font-size: 17px; }

  .btn--sm { min-height: 40px; padding: 0 13px; font-size: 13px; }

  .hero-actions,
  .cta-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .hero-actions .btn,
  .cta-actions .btn { width: 100%; }

  .hero-note { margin-top: 22px; }

  .hero-art {
    height: 396px;
    margin-top: 4px;
  }

  .art-panel { inset: 5% 0 4% 0; border-radius: 22px; }

  .ledger {
    width: min(calc(100% - 44px), 420px);
    padding: 15px;
    transform: rotate(-1.2deg);
  }

  .ledger-title { font-size: 16px; }

  .chip {
    padding: 9px 11px;
    font-size: 10.5px;
  }

  .chip--auto { top: 2%; right: 2%; }
  .chip--dupe { bottom: 2%; left: 2%; }

  .row-bar { width: 54px; }

  .section-lede { font-size: 15px; }

  .footer-inner { flex-direction: column; align-items: flex-start; gap: 12px; }
  .footer-tag { margin: 0; }
}

@media (max-width: 360px) {
  .hero-title { font-size: 2.3rem; }
  .ledger { padding: 13px; }
  .row-name { font-size: 12px; }
  .row-bar { width: 46px; }
  .chip--auto { right: 0; }
  .chip--dupe { left: 0; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation: none !important;
    transition: none !important;
  }
}
